// Third-party attribution page.
//
// MIT, ISC, BSD and zlib all require the copyright notice and permission text
// to be reachable by anyone who receives the software. The notice file is
// generated by scripts/gen-notices.mjs into mochi/public/, so this page just
// renders whatever the build shipped. Never hardcode the list here.

import React, { useEffect, useState } from 'react';
import { ArrowLeft } from 'lucide-react';
import { useI18n } from '../i18n/context';

function noticeUrl(): string {
  const env = (import.meta as unknown as { env?: Record<string, string | undefined> }).env ?? {};
  const base = env.BASE_URL ?? '/';
  return `${base.endsWith('/') ? base : `${base}/`}THIRD_PARTY_NOTICES.txt`;
}

export const CreditsPage: React.FC = () => {
  const { t } = useI18n();
  const [text, setText] = useState<string>('');
  const [error, setError] = useState<boolean>(false);

  useEffect(() => {
    let cancelled = false;
    fetch(noticeUrl())
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.text();
      })
      .then((body) => {
        if (!cancelled) setText(body);
      })
      .catch(() => {
        if (!cancelled) setError(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#090b10] text-slate-900 dark:text-[#ffffff] transition-colors">
      <div className="max-w-4xl mx-auto px-6 py-10">
        <a
          href="/"
          className="inline-flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          <span className="mochi-wordmark text-sm">MOCHI</span>
        </a>

        <h1 className="mt-8 text-2xl font-semibold tracking-tight">{t.pages.creditsTitle}</h1>
        <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
          {t.pages.creditsIntro}
        </p>

        {error && (
          <p className="mt-8 text-sm text-slate-600 dark:text-slate-400">
            {t.pages.creditsUnavailable}{' '}
            <a className="underline" href={noticeUrl()}>
              THIRD_PARTY_NOTICES.txt
            </a>
          </p>
        )}

        {!error && text.length === 0 && (
          <p className="mt-8 text-sm text-slate-500 dark:text-slate-400">{t.pages.creditsLoading}</p>
        )}

        {text.length > 0 && (
          <pre className="mt-8 whitespace-pre-wrap break-words font-mono text-[11px] leading-relaxed text-slate-700 dark:text-slate-300 bg-white dark:bg-[#12141a] border border-slate-200 dark:border-white/[0.08] rounded-xl p-5 overflow-x-auto">
            {text}
          </pre>
        )}
      </div>
    </div>
  );
};

export default CreditsPage;
